import { DLMMStatsPairsPath } from '@/apis/path'
import { formatCoinTypesParams } from '@/utils/pool'
import { useFetch } from '@cetus/hooks'
import { useSdk, useSdkStore } from '@cetus/sdk-factory'
import { camelCaseObject } from '@cetus/utils'
import { groupBy } from 'lodash-es'
import { useCallback } from 'react'
import useWrapDlmmPoolData from './useWrapDlmmPoolData'
import { wrapGetDlmmPoolParams } from './utils'

export default function useGetDlmmPoolList() {
  const dlmmSdk = useSdk('dlmm')
  const { isInitialized } = useSdkStore()
  const { fetchByApi } = useFetch()
  const { wrapDlmmGroupedPoolData } = useWrapDlmmPoolData()
  const getDlmmPoolListFromApi = async (params: any) => {
    try {
      const apiParams = { ...params }
      const coinTypes = formatCoinTypesParams(params?.coin_type)
      if (coinTypes) {
        apiParams['coin_type'] = coinTypes
      }
      const wrapApiParams = wrapGetDlmmPoolParams(apiParams)
      const res = await fetchByApi(DLMMStatsPairsPath, 'POST', wrapApiParams)
      // if ((!res?.data?.list || res?.data?.list?.length === 0) && envConfigs.env === 'testnet') {
      //   throw Error('testnet no data')
      // }
      if (res?.data?.list) {
        const poolList = wrapDlmmGroupedPoolData(res?.data?.list)
        console.log('🚀 ~ file: useGetDlmmPoolList.ts:22 ~ poolList ~ poolList:', res?.data?.list, poolList)

        return {
          list: poolList,
          total: res?.data?.total
        }
      }
    } catch (error) {
      console.log('🚀 ~ getDlmmPoolListFromApi ~ error:', error)
      return await getDlmmPoolListFromSdk(params)
    }

    return {
      list: [],
      total: 0
    }
  }

  const getDlmmPoolListFromSdk = async (params: any) => {
    try {
      const dlmmPoolList = await dlmmSdk!.Pool.getPools()
      let list: any
      const originList = dlmmPoolList?.data?.map(item => camelCaseObject(item))
      console.log('🚀 ~ getDlmmPoolList ~ dlmmPoolList:', originList, dlmmPoolList)
      if (originList?.length > 0) {
        // if (params?.pools) {
        //   list = originList?.filter((item: any) => params?.pools && params?.pools[0]?.toLocaleLowerCase() == item?.pool.toLocaleLowerCase())
        // }

        // if (params?.pool) {
        //   list = originList?.filter((item: any) => params?.pool && params?.pool?.toLocaleLowerCase() == item?.pool.toLocaleLowerCase())
        // }

        // // 支持coin_type筛选
        // if (params?.coin_type) {
        //   const coinArr = params?.coin_type?.split(',')?.map(item => extractStructTagFromType(item).source_address)
        //   list = originList?.filter((item: any) => {
        //     const coinTypeA = extractStructTagFromType(item?.coinA?.coinType).source_address
        //     const coinTypeB = extractStructTagFromType(item?.coinB?.coinType).source_address
        //     if (coinArr?.length > 1 && coinArr.includes(coinTypeA) && coinArr.includes(coinTypeB)) {
        //       return true
        //     } else if (coinArr?.length === 1 && (coinArr.includes(coinTypeA) || coinArr.includes(coinTypeB))) {
        //       return true
        //     } else {
        //       return false
        //     }
        //   })
        // }

        // // 支持vaults筛选
        // if (params?.is_vaults) {
        //   list = originList?.filter((item: any) => item?.is_vaults)
        // }

        // // 支持farms筛选
        // if (params?.has_farming && !params?.is_vaults && !params?.has_mining && !params?.no_incentives) {
        //   list = originList?.filter((item: any) => item?.farmingRewarder && item?.farmingRewarder?.clmmPool)
        // }

        const groupedPools = groupBy(originList, 'poolType')
        list = wrapDlmmGroupedPoolData(
          Object.values(groupedPools).map((item: any) => {
            return {
              tvl: '--',
              vol: '--',
              fees: '--',
              totalApr: '--',
              id: item[0]?.poolType,
              coinTypeA: item[0]?.coinTypeA,
              coinTypeB: item[0]?.coinTypeB,
              pools: [...item]
            }
          }),
          true
        )
        console.log('🚀 ~ getDlmmPoolListFromSdk list:', list)

        return {
          list,
          total: list?.length || 0
        }
      }
    } catch (error) {
      console.log('getDlmmPoolListFromSdk', error)
      return {
        list: [],
        total: 0
      }
    }
  }

  const getDlmmPoolList = useCallback(
    (params: any) => {
      if (isInitialized) {
        // return getDlmmPoolListFromSdk(params).then(res => {
        //   return res
        // })
        return getDlmmPoolListFromApi(params).then(res => {
          return res
        })
      } else {
        setTimeout(() => {
          getDlmmPoolList(params)
        }, 1000)
      }
    },
    [isInitialized]
  )

  return {
    getDlmmPoolList
  }
}
